curl -s -X POST https://slack.com/api/conversations.list -d "token=<TOKEN>&types=public_channel&limit=100" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'launch' in ch['name'].lower():
            print(ch['id'], ch['name'])
else:
    print(data)
"

curl -s -X POST https://slack.com/api/conversations.history -d "token=<TOKEN>&channel=C_LAUNCH&limit=100" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        print(json.dumps(msg, indent=2))
else:
    print(data)
"

